// Every animated bind at `seconds` on the toolbox timeline, keyed by bind id
// (manifest.json maps ids to IR paths). Animated path geometry is not here:
// the component reads the pre-parsed PATH_* series itself.
export function sampleBinds(seconds: number) {
  "worklet";
  const tick = ticksAt(seconds, TIMELINE.fps, TIMELINE.ticksPerFrame);
  const frame = tick / TIMELINE.ticksPerFrame;
  return {
    b3: seconds, // master clock (seconds)
    b4: evaluateTrack(T_b4, tick) as number, // Animated Value scale (3 keys)
    b8: evaluateTrack(T_b8, tick) as number, // Animated Value drift (2 keys)
    b12: evaluateTrack(T_b12, tick) as number, // Animated Value contrast (4 keys)
    b18: seriesLerpN(S_b18, frame), // derived from skr.stops (animated: skr.stops); sampled 301 frames
    b20: seriesLerpN(S_b20, frame), // derived from skr.stops, skr.interpolation, skr.space (animated: skr.stops); sampled 301 frames
  };
}
